import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"TUI Explorer","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/tui.md","filePath":"advanced/tui.md","lastUpdated":1784864016000}'),s={name:"advanced/tui.md"};function n(r,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="tui-explorer" tabindex="-1">TUI Explorer <a class="header-anchor" href="#tui-explorer" aria-label="Permalink to &quot;TUI Explorer&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>swag2mcp includes a built-in TUI (Terminal User Interface) for interactive API exploration. It is a full-screen terminal application that lets you search, browse, inspect, and invoke API endpoints without leaving the terminal.</p><h2 id="launch" tabindex="-1">Launch <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;Launch&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>If no config file exists, the TUI will automatically start the initialization wizard first.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p>The TUI has three modes, switchable with the <code>Tab</code> key:</p><h3 id="search-mode" tabindex="-1">Search mode <a class="header-anchor" href="#search-mode" aria-label="Permalink to &quot;Search mode&quot;">​</a></h3><p>Full-text search across all endpoints in all specs. Supports the same query syntax as the <code>search</code> MCP tool.</p><ul><li>Type a query to search endpoint names, paths, and descriptions</li><li>Filter results by method, tag, or path</li><li>View endpoint details with a single keystroke</li><li>Navigate through results with pagination (10 items per page)</li></ul><h3 id="browse-mode" tabindex="-1">Browse mode <a class="header-anchor" href="#browse-mode" aria-label="Permalink to &quot;Browse mode&quot;">​</a></h3><p>Tree navigation through the spec hierarchy:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>Navigate down the tree to find specific endpoints</li><li>View endpoint details (parameters, request body, responses)</li><li>Invoke the API directly from the TUI</li><li>Save endpoint details as a JSON file</li></ul><h3 id="auth-mode" tabindex="-1">Auth mode <a class="header-anchor" href="#auth-mode" aria-label="Permalink to &quot;Auth mode&quot;">​</a></h3><p>View authentication tokens and headers for any spec. Useful for debugging or generating curl commands.</p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Navigate up/down</td></tr><tr><td><code>Enter</code></td><td>Select or open</td></tr><tr><td><code>Esc</code></td><td>Go back one level</td></tr><tr><td><code>Tab</code></td><td>Switch between Search, Browse, and Auth modes</td></tr><tr><td><code>/</code></td><td>Focus search input</td></tr><tr><td><code>N</code> / <code>P</code></td><td>Next / previous page</td></tr><tr><td><code>B</code></td><td>Back to previous screen</td></tr><tr><td><code>M</code></td><td>Return to main menu</td></tr><tr><td><code>S</code></td><td>Save endpoint detail as JSON file</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>Quit</td></tr></tbody></table><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><p>The TUI goes through these states as you navigate:</p><ol><li><strong>Loading</strong> — loading data from the workspace</li><li><strong>Search</strong> — search mode with query input</li><li><strong>Browse</strong> — browse mode with spec list</li><li><strong>Spec List</strong> — list of all specs</li><li><strong>Collection List</strong> — collections within a spec</li><li><strong>Tag List</strong> — tags within a collection</li><li><strong>Endpoint List</strong> — endpoints within a tag</li><li><strong>Endpoint Detail</strong> — full endpoint information</li><li><strong>Invoke Result</strong> — API call result</li><li><strong>Error</strong> — error state with message</li></ol><h2 id="endpoint-detail-view" tabindex="-1">Endpoint detail view <a class="header-anchor" href="#endpoint-detail-view" aria-label="Permalink to &quot;Endpoint detail view&quot;">​</a></h2><p>When you select an endpoint, the TUI shows:</p><ul><li>HTTP method and path</li><li>Base URL and full URL</li><li>Summary and description</li><li>All parameters (name, location, type, required)</li><li>Request body schema (if applicable)</li><li>Response codes and schemas</li><li>Deprecation status</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Terminal size:</strong> At least 80×24 characters</li><li><strong>Terminal emulator:</strong> Works in most modern terminals (iTerm2, Terminal.app, GNOME Terminal, Windows Terminal, etc.)</li><li><strong>SSH:</strong> Works over SSH connections</li></ul><h2 id="important-notes" tabindex="-1">Important notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important notes&quot;">​</a></h2><ul><li><strong>Auto-init</strong> — if no config file exists, the TUI automatically starts the initialization wizard</li><li><strong>Pagination</strong> — lists are paginated at 10 items per page. Use <code>N</code> and <code>P</code> to navigate</li><li><strong>Save endpoint details</strong> — press <code>S</code> in the endpoint detail view to save the full detail as a JSON file in the current directory</li><li><strong>Auth mode</strong> — shows tokens and headers for debugging. In production, the auth tool can be disabled with <code>--disable-llm-auth</code></li></ul>',29)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
